let audioContext,masterGain;
const decoded=new Map();
export function getGameVolume(){try{return Math.max(0,Math.min(1,Number(localStorage.getItem('playform.game-volume')??.7)))}catch{return .7}}
export function setGameVolume(value){const volume=Math.max(0,Math.min(1,Number(value)||0));try{localStorage.setItem('playform.game-volume',String(volume))}catch{}if(masterGain)masterGain.gain.value=volume;return volume}
export function getAudioContext(){audioContext??=new (window.AudioContext||window.webkitAudioContext)();if(!masterGain){masterGain=audioContext.createGain();masterGain.gain.value=getGameVolume();masterGain.connect(audioContext.destination)}if(audioContext.state==='suspended')audioContext.resume();return audioContext}
export async function playProjectSound(sound){if(!sound)return;const ctx=getAudioContext();let buffer=decoded.get(sound.data);if(!buffer){buffer=ctx.decodeAudioData(await(await fetch(sound.data)).arrayBuffer());decoded.set(sound.data,buffer)}const source=ctx.createBufferSource();source.buffer=await buffer;source.connect(masterGain);source.start();return source}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function encodeWav(channels,sampleRate){const length=channels[0].length,buffer=new ArrayBuffer(44+length*channels.length*2),view=new DataView(buffer),text=(offset,s)=>{for(let i=0;i<s.length;i++)view.setUint8(offset+i,s.charCodeAt(i))};text(0,'RIFF');view.setUint32(4,buffer.byteLength-8,true);text(8,'WAVE');text(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,channels.length,true);view.setUint32(24,sampleRate,true);view.setUint32(28,sampleRate*channels.length*2,true);view.setUint16(32,channels.length*2,true);view.setUint16(34,16,true);text(36,'data');view.setUint32(40,length*channels.length*2,true);let offset=44;for(let i=0;i<length;i++)for(const channel of channels){const value=Math.max(-1,Math.min(1,channel[i]));view.setInt16(offset,value<0?value*32768:value*32767,true);offset+=2}return buffer}
export function openSoundEditor({project,onChange,notify}){
 const dialog=document.createElement('dialog');dialog.className='sound-editor';document.body.append(dialog);const $=s=>dialog.querySelector(s);let raw=null,source=null,selected=null,generation=0;
 dialog.innerHTML=`<header class="art-title"><h2>Sound & SFX Editor</h2><span></span><button id="close-sound" aria-label="Close sound editor">×</button></header><div class="sound-layout"><aside class="sound-library"><header>Project audio</header><div id="sound-list"></div><label class="sound-import">Import audio<input type="file" id="sound-import" accept="audio/wav,audio/mpeg,audio/ogg,audio/mp4,audio/flac,audio/webm"></label></aside><main class="sound-main"><label>Name<input id="sound-name" value="Coin collect" maxlength="80"></label><canvas id="waveform" width="680" height="170" aria-label="Audio waveform"></canvas><div class="sound-transport"><button id="play-sound">▶ Play</button><button id="stop-sound">■ Stop</button><span id="sound-duration"></span></div><div class="sound-settings"><label>Trim start (s)<input id="trim-start" type="number" min="0" step="0.01" value="0"></label><label>Trim end (s)<input id="trim-end" type="number" min="0" step="0.01" value="0.3"></label><label>Volume<input id="sound-gain" type="range" min="0" max="2" step="0.05" value="0.6"></label><label>Fade in (s)<input id="fade-in" type="number" min="0" max="2" step="0.01" value="0.01"></label><label>Fade out (s)<input id="fade-out" type="number" min="0" max="2" step="0.01" value="0.06"></label></div><details class="sfx-generator" open><summary>SFX Generator</summary><div class="sound-presets">${['Coin','Jump','Hit','Laser','Power-up'].map(p=>`<button data-sfx="${p}">${p}</button>`).join('')}</div><div class="sound-settings"><label>Wave<select id="sfx-wave"><option>sine</option><option>square</option><option>triangle</option><option>sawtooth</option><option>noise</option></select></label><label>Start pitch (Hz)<input id="sfx-start" type="number" min="20" max="20000" value="880"></label><label>End pitch (Hz)<input id="sfx-end" type="number" min="20" max="20000" value="1320"></label><label>Duration (s)<input id="sfx-duration" type="number" min="0.03" max="10" step="0.01" value="0.25"></label></div><button id="generate-sfx">Generate SFX</button></details><footer class="art-footer"><button id="export-wav">Download sound (.wav)</button><span></span><button class="primary" id="save-sound">Save to project</button></footer></main></div>`;
 function renderList(){$('#sound-list').innerHTML=(project.sounds||[]).map(s=>`<div class="sound-library-item"><button data-load-sound="${esc(s.id)}" class="${selected===s.id?'active':''}">♫ ${esc(s.name)}</button><button data-delete-sound="${esc(s.id)}" aria-label="Delete ${esc(s.name)}">×</button></div>`).join('');dialog.querySelectorAll('[data-load-sound]').forEach(b=>b.onclick=async()=>{const s=project.sounds.find(s=>s.id===b.dataset.loadSound);if(!s)return;selected=s.id;$('#sound-name').value=s.name;try{raw=await getAudioContext().decodeAudioData(await(await fetch(s.data)).arrayBuffer());$('#sound-gain').value=1;$('#fade-in').value=0;$('#fade-out').value=0;resetTrim();renderList()}catch{notify('Could not decode that audio file.')}});dialog.querySelectorAll('[data-delete-sound]').forEach(b=>b.onclick=()=>{onChange({remove:b.dataset.deleteSound});if(selected===b.dataset.deleteSound)selected=null;renderList()})}
 function resetTrim(){$('#trim-start').value=0;$('#trim-end').value=raw.duration.toFixed(3);$('#sound-duration').textContent=`${raw.duration.toFixed(2)} s`;paint()}
 function settings(){const start=+$('#trim-start').value,end=+$('#trim-end').value,gain=+$('#sound-gain').value,fadeIn=+$('#fade-in').value,fadeOut=+$('#fade-out').value;if(!raw||!Number.isFinite(start)||!Number.isFinite(end)||start<0||end<=start||end>raw.duration+.002)throw Error('Trim end must be after start and within the audio.');if(![gain,fadeIn,fadeOut].every(Number.isFinite)||fadeIn<0||fadeOut<0)throw Error('Enter valid volume and fade values.');return{start,end,gain,fadeIn,fadeOut}}
 function processed(){const{start,end,gain,fadeIn,fadeOut}=settings(),first=Math.floor(start*raw.sampleRate),length=Math.min(raw.length-first,Math.floor((end-start)*raw.sampleRate)),channels=[];for(let channel=0;channel<Math.min(2,raw.numberOfChannels);channel++){const input=raw.getChannelData(channel),out=new Float32Array(length);for(let i=0;i<length;i++){const envelope=Math.min(1,fadeIn?i/raw.sampleRate/fadeIn:1,fadeOut?(length-i)/raw.sampleRate/fadeOut:1);out[i]=Math.max(-1,Math.min(1,input[first+i]*gain*envelope))}channels.push(out)}return{channels,sampleRate:raw.sampleRate}}
 function paint(){const c=$('#waveform'),ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.fillStyle='#171a25';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#333343';for(let y=0;y<h;y+=34){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}if(!raw)return;const input=raw.getChannelData(0),step=Math.max(1,Math.floor(input.length/w));ctx.strokeStyle='#b789e3';ctx.beginPath();for(let x=0;x<w;x++){let max=0;for(let i=x*step;i<Math.min(input.length,(x+1)*step);i++)max=Math.max(max,Math.abs(input[i]));ctx.moveTo(x,h/2-max*h*.45);ctx.lineTo(x,h/2+max*h*.45)}ctx.stroke();const start=+$('#trim-start').value/raw.duration*w,end=+$('#trim-end').value/raw.duration*w;ctx.fillStyle='#070912a0';ctx.fillRect(0,0,start,h);ctx.fillRect(end,0,w-end,h);ctx.strokeStyle='#e4c16f';for(const x of [start,end]){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}}
 async function generate(){const start=+$('#sfx-start').value,end=+$('#sfx-end').value,duration=+$('#sfx-duration').value,wave=$('#sfx-wave').value;if(![start,end,duration].every(Number.isFinite)||start<20||start>20000||end<20||end>20000||duration<.03||duration>10){notify('Use 20–20,000 Hz and a duration from 0.03–10 seconds.');return}const ctx=getAudioContext();raw=ctx.createBuffer(1,Math.floor(ctx.sampleRate*duration),ctx.sampleRate);const samples=raw.getChannelData(0);let phase=0;for(let i=0;i<samples.length;i++){phase+=(start+(end-start)*(i/samples.length))/ctx.sampleRate;const p=phase%1;samples[i]=(wave==='sine'?Math.sin(2*Math.PI*phase):wave==='square'?(p<.5?1:-1):wave==='triangle'?1-4*Math.abs(p-.5):wave==='sawtooth'?2*p-1:Math.random()*2-1)*.7}selected=null;resetTrim();renderList();generation++}
 function soundButtons(){const stopButton=$('#stop-sound');if(stopButton){stopButton.disabled=!source;stopButton.title=source?'Stop this sound':'Play a sound before stopping it.'}}
 function stop(){if(source){try{source.stop()}catch{}source=null}soundButtons()}
 $('#close-sound').onclick=()=>dialog.close();$('#stop-sound').onclick=stop;$('#generate-sfx').onclick=generate;$('#play-sound').onclick=()=>{try{stop();const{channels,sampleRate}=processed(),ctx=getAudioContext(),buffer=ctx.createBuffer(channels.length,channels[0].length,sampleRate);channels.forEach((data,i)=>buffer.copyToChannel(data,i));source=ctx.createBufferSource();source.buffer=buffer;source.connect(masterGain);const currentSource=source;source.onended=()=>{if(source===currentSource){source=null;soundButtons()}};source.start();soundButtons()}catch(error){notify(error.message)}};for(const id of ['#trim-start','#trim-end'])$(id).oninput=paint;
 const presets={Coin:['square',880,1568,.18],Jump:['sine',220,640,.22],Hit:['noise',180,40,.2],Laser:['sawtooth',1200,80,.3],'Power-up':['triangle',440,1760,.6]};dialog.querySelectorAll('[data-sfx]').forEach(b=>b.onclick=()=>{const[wave,start,end,duration]=presets[b.dataset.sfx];$('#sfx-wave').value=wave;$('#sfx-start').value=start;$('#sfx-end').value=end;$('#sfx-duration').value=duration;$('#sound-name').value=b.dataset.sfx;generate()});$('#sound-import').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>5e6){notify('Choose an audio file under 5 MB.');return}try{const buffer=await getAudioContext().decodeAudioData(await file.arrayBuffer());if(buffer.duration>30){notify('Choose an audio clip up to 30 seconds long.');return}raw=buffer;selected=null;$('#sound-name').value=file.name.replace(/\.[^.]+$/,'').slice(0,80);resetTrim();renderList()}catch{notify('This browser could not decode that audio format.')}};
 function wav(){const{channels,sampleRate}=processed();return new Blob([encodeWav(channels,sampleRate)],{type:'audio/wav'})}
 $('#export-wav').onclick=()=>{try{const url=URL.createObjectURL(wav()),a=document.createElement('a');a.href=url;a.download=($('#sound-name').value.trim()||'sfx')+'.wav';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){notify(e.message)}};$('#save-sound').onclick=async()=>{try{const blob=wav();if(blob.size>1500000){notify('Trim the clip to keep the WAV under 1.5 MB.');return}const name=$('#sound-name').value.trim();if(!name){notify('Name the sound first.');return}const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob)});selected=selected||crypto.randomUUID();onChange({sound:{id:selected,name,data,duration:(+$('#trim-end').value)-(+$('#trim-start').value)}});renderList();notify('Audio saved to the project.')}catch(e){notify(e.message)}};dialog.onclose=()=>{stop();dialog.remove()};dialog.showModal();renderList();generate();soundButtons();
}
